mod execution { use super::*;#[derive(Default)]pub struct Entry{pub stop:AtomicBool,wake:tokio::sync::Notify}impl Entry{pub fn stopping(&self)->bool{self.stop.load(Ordering::Acquire)}pub async fn wait_stop(&self){loop{let wait=self.wake.notified();if self.stopping(){return}wait.await;}}pub fn cancel(&self){self.stop.store(true,Ordering::Release);self.wake.notify_waiters();}} }
