const LOG_LINES:usize=256;const LOG_BYTES:usize=256*1024;
#[derive(Clone,Debug,Serialize,Deserialize)]struct BatchLog{sequence:u64,level:String,phase:String,statement:Option<u64>,row:Option<u64>,message:String,sql_template:Option<String>,ts_ms:u64,elapsed_ms:Option<u64>,affected_rows:Option<u64>,error_code:Option<String>}
#[derive(Default)]struct Progress{scanned:u64,executed:u64,errors:u64,affected:u64,scan_complete:bool,parse_error:Option<String>,logs:VecDeque<BatchLog>,bytes:usize,next:u64,dropped:u64}
#[derive(Debug,Serialize)]pub struct MultiResult{scanned:u64,executed:u64,errors:u64,affected:u64,scan_complete:bool,parse_error:Option<String>,logs:Vec<BatchLog>}
mod before {include!(concat!(env!("OUT_DIR"),"/before.rs"));}mod after {include!(concat!(env!("OUT_DIR"),"/after.rs"));}
struct TempRoot(PathBuf);impl TempRoot{fn new()->Result<Self>{let p=std::env::temp_dir().join(format!("navkit_perf_{}_{}",std::process::id(),std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH)?.as_nanos()));std::fs::create_dir(&p)?;Ok(Self(p))}fn file(&self,name:&str,text:&str)->String{let p=self.0.join(name);std::fs::write(&p,text).unwrap();p.to_str().unwrap().into()}}
impl Drop for TempRoot{fn drop(&mut self){if let Err(e)=std::fs::remove_dir_all(&self.0){eprintln!("isolated fixture cleanup failed: {e}");}}}
fn sql_file(root:&TempRoot,rows:usize,payload:usize)->Result<(String,u64)>{let p=root.0.join("large.sql");let mut f=std::io::BufWriter::new(std::fs::File::create(&p)?);writeln!(f,"CREATE TABLE items(id INTEGER PRIMARY KEY,note TEXT NOT NULL);")?;let body="真实;SQL''值".repeat(payload/16+1);for i in 1..=rows{writeln!(f,"INSERT INTO items VALUES({i},'{body}');")?;}writeln!(f,"CREATE INDEX ix_items_note ON items(note); SELECT id,note FROM items;")?;f.flush()?;Ok((p.to_str().unwrap().into(),std::fs::metadata(p)?.len()))}
fn millis(t:Instant)->f64{t.elapsed().as_secs_f64()*1000.0}
fn audit_check(r:&MultiResult){assert!(r.logs.len()<=LOG_LINES);assert!(r.logs.iter().all(|l|l.message.contains("SHA-256")&&l.sql_template.as_ref().is_some_and(|s|!s.contains("真实")&&s.len()<=2048)));}
async fn sqlite_run(variant:&str,conn:&mut sqlx::SqliteConnection,file:&str,stop:bool,entry:Arc<Entry>)->(Result<MultiResult>,MultiResult){if variant=="before"{before::sqlite(conn,file,stop,entry).await}else{after::sqlite(conn,file,stop,entry).await}}
async fn sqlite_bench(rows:usize,rounds:usize,payload:usize)->Result<serde_json::Value>{let root=TempRoot::new()?;let(file,bytes)=sql_file(&root,rows,payload)?;let mut samples=vec![];let mut parses=vec![];
 for round in 0..rounds+1{let order=if round%2==0{["before","after"]}else{["after","before"]};for variant in order{let start=Instant::now();let parsed=if variant=="before"{before::parse(&file,"sqlite")?}else{after::parse(&file,"sqlite")?};let parse_ms=millis(start);assert_eq!(parsed,rows as u64+3);let options=sqlx::sqlite::SqliteConnectOptions::new().filename(root.0.join(format!("{variant}-{round}.sqlite"))).create_if_missing(true).journal_mode(sqlx::sqlite::SqliteJournalMode::Wal).synchronous(sqlx::sqlite::SqliteSynchronous::Normal);let mut c=sqlx::SqliteConnection::connect_with(&options).await?;let start=Instant::now();let(result,r)=sqlite_run(variant,&mut c,&file,true,Arc::default()).await;let elapsed_ms=millis(start);result?;assert_eq!((r.executed,r.errors,r.affected),(rows as u64+3,0,rows as u64+2));assert!(r.scan_complete);audit_check(&r);let count:i64=sqlx::query_scalar("SELECT COUNT(*) FROM items").fetch_one(&mut c).await?;assert_eq!(count,rows as i64);c.close().await?;if round>0{samples.push(serde_json::json!({"variant":variant,"round":round,"ms":elapsed_ms,"executed":r.executed,"affected":r.affected,"stored_rows":count}));parses.push(serde_json::json!({"variant":variant,"round":round,"ms":parse_ms}));}}}
 Ok(serde_json::json!({"engine":"sqlite","path":"product-scanner-worker-audit","history_registry_shim":true,"journal":"WAL/NORMAL","affected_semantics":"native SQLite changes() receipts; SELECT/index DDL repeat last DML changes, not net inserted rows","rows":rows,"bytes":bytes,"rounds":rounds,"warmup_per_variant":1,"samples":samples,"parse_samples":parses}))}
async fn sqlite_semantics()->Result<()> {let root=TempRoot::new()?;for v in ["before","after"]{let mut c=sqlx::SqliteConnection::connect("sqlite::memory:").await?;
 let file=root.file("errors.sql","CREATE TABLE items(id INTEGER PRIMARY KEY,note TEXT); INSERT INTO items VALUES(1,'one'); INSERT INTO items VALUES(1,'duplicate'); INSERT INTO items VALUES(2,'two'); SELECT * FROM items;");let(e,r)=sqlite_run(v,&mut c,&file,false,Arc::default()).await;assert!(e.is_err());assert_eq!((r.executed,r.errors,r.affected),(5,1,3));assert!(r.scan_complete);assert!(r.parse_error.is_none());assert!(r.logs.iter().any(|l|l.error_code.is_some()));
 let file=root.file("stop.sql","INSERT INTO items VALUES(3,'prefix'); INSERT INTO items VALUES(3,'duplicate'); INSERT INTO items VALUES(4,'never');");let(e,r)=sqlite_run(v,&mut c,&file,true,Arc::default()).await;assert!(e.is_err());assert_eq!((r.executed,r.errors,r.affected),(2,1,1));assert_eq!(sqlx::query_scalar::<_,i64>("SELECT COUNT(*) FROM items WHERE id=4").fetch_one(&mut c).await?,0);
 let file=root.file("temp.sql","CREATE TEMP TABLE local_values(v INTEGER); INSERT INTO local_values VALUES(7); INSERT INTO items SELECT v,'temp-value' FROM local_values; CREATE TABLE audit(v INTEGER); CREATE TRIGGER tr AFTER INSERT ON items BEGIN INSERT INTO audit VALUES(CASE WHEN NEW.id>0 THEN NEW.id ELSE 0 END); END; INSERT INTO items VALUES(8,'trigger;value'); SELECT * FROM items; SELECT 'broken");let(e,r)=sqlite_run(v,&mut c,&file,true,Arc::default()).await;assert!(e.is_err());assert_eq!((r.executed,r.errors),(7,0));assert!(r.parse_error.is_some());assert_eq!(sqlx::query_scalar::<_,i64>("SELECT v FROM audit").fetch_one(&mut c).await?,8);
 let file=root.file("transaction.sql","INSERT INTO items VALUES(9,'transaction'); COMMIT; INSERT INTO items VALUES(10,'never');");c.execute("BEGIN").await?;let(e,r)=sqlite_run(v,&mut c,&file,true,Arc::default()).await;assert!(e.is_err());assert_eq!(r.executed,1);c.execute("ROLLBACK").await?;assert_eq!(sqlx::query_scalar::<_,i64>("SELECT COUNT(*) FROM items WHERE id IN(9,10)").fetch_one(&mut c).await?,0);
 let file=root.file("large-results.sql","WITH RECURSIVE n(x) AS(VALUES(1) UNION ALL SELECT x+1 FROM n WHERE x<10000) SELECT x FROM n; INSERT INTO items VALUES(11,'after-drain');");let(e,r)=sqlite_run(v,&mut c,&file,true,Arc::default()).await;e?;assert_eq!((r.executed,r.affected),(2,2));c.close().await?;
 }println!("PASS sqlite errors stop-on-error temp-table trigger malformed-tail transaction-control-rejection rollback result-drain");Ok(())}
async fn sqlite_cancel()->Result<()> {let root=TempRoot::new()?;for v in ["before","after"]{let mut c=sqlx::SqliteConnection::connect("sqlite::memory:").await?;let entry=Arc::<Entry>::default();let e=entry.clone();{let mut h=c.lock_handle().await?;h.set_progress_handler(1000,move||!e.stopping());}let file=root.file("cancel.sql",&format!("CREATE TABLE items(v INTEGER); INSERT INTO items VALUES(1); WITH RECURSIVE n(x) AS(VALUES(1) UNION ALL SELECT x+1 FROM n WHERE x<1000000000) SELECT sum(x) FROM n; {}","INSERT INTO items VALUES(2);\n".repeat(10000)));let e=entry.clone();let stop=tokio::spawn(async move{tokio::time::sleep(Duration::from_millis(100)).await;e.cancel();});let(e,r)=tokio::time::timeout(Duration::from_secs(10),sqlite_run(v,&mut c,&file,true,entry)).await?;stop.await?;assert!(e.is_err());assert_eq!((r.executed,r.errors),(3,1));assert!(r.scanned<10003);{let mut h=c.lock_handle().await?;h.remove_progress_handler();}assert_eq!(sqlx::query_scalar::<_,i64>("SELECT COUNT(*) FROM items").fetch_one(&mut c).await?,1);c.close().await?;}println!("PASS sqlite real-VM cancel prefix-preservation bounded-scan no-tail-replay");Ok(())}

fn isolated_database()->Result<String>{let s=std::env::var("NAVKIT_PERF_DATABASE")?;if !s.strip_prefix("navkit_perf_").is_some_and(|t|t.len()==32&&t.bytes().all(|b|b.is_ascii_hexdigit())){bail!("Require externally created navkit_perf_uuid isolated database");}Ok(s)}
async fn mysql_connection()->Result<sqlx::MySqlConnection>{let db=isolated_database()?;let host=std::env::var("NAVKIT_MYSQL_HOST").unwrap_or("127.0.0.1".into());if !matches!(host.as_str(),"127.0.0.1"|"localhost"|"::1"){bail!("Local MySQL only");}let opts=sqlx::mysql::MySqlConnectOptions::new().host(&host).port(std::env::var("NAVKIT_MYSQL_PORT").ok().and_then(|s|s.parse().ok()).unwrap_or(3306)).username(&std::env::var("NAVKIT_MYSQL_USER").unwrap_or("root".into())).password(&std::env::var("NAVKIT_MYSQL_PASSWORD")?).database(&db);Ok(sqlx::MySqlConnection::connect_with(&opts).await?)}
async fn pg_connection()->Result<sqlx::PgConnection>{let db=isolated_database()?;let opts=sqlx::postgres::PgConnectOptions::new().host(&std::env::var("NAVKIT_PG_HOST").unwrap_or("127.0.0.1".into())).port(5432).username(&std::env::var("NAVKIT_PG_USER").unwrap_or("postgres".into())).password(&std::env::var("NAVKIT_PG_PASSWORD").unwrap_or_default()).database(&db);Ok(sqlx::PgConnection::connect_with(&opts).await?)}
macro_rules! remote_benchmark {($name:ident,$connect:ident,$worker:ident,$engine:expr)=>{async fn $name(rows:usize,rounds:usize,payload:usize)->Result<serde_json::Value>{let root=TempRoot::new()?;let(file,_)=sql_file(&root,rows,payload)?;if $engine=="mysql"{let s=std::fs::read_to_string(&file)?.replace("CREATE INDEX ix_items_note ON items(note)","CREATE INDEX ix_items_note ON items(note(32))");std::fs::write(&file,s)?;}let bytes=std::fs::metadata(&file)?.len();let mut samples=vec![];let mut parses=vec![];
for round in 0..rounds+1 {for variant in if round%2==0{["before","after"]}else{["after","before"]}{let start=Instant::now();let parsed=if variant=="before"{before::parse(&file,$engine)?}else{after::parse(&file,$engine)?};let parse_ms=millis(start);assert_eq!(parsed,rows as u64+3);let mut c=$connect().await?;c.execute("DROP TABLE IF EXISTS items").await?;let start=Instant::now();let(e,r)=if variant=="before"{before::$worker(&mut c,&file,true,Arc::default()).await}else{after::$worker(&mut c,&file,true,Arc::default()).await};let elapsed_ms=millis(start);e?;assert_eq!((r.executed,r.errors,r.affected),(rows as u64+3,0,if $engine=="pg" {rows as u64*2}else{rows as u64}));assert!(r.scan_complete);audit_check(&r);let count:i64=sqlx::query_scalar("SELECT COUNT(*) FROM items").fetch_one(&mut c).await?;assert_eq!(count,rows as i64);c.close().await?;if round>0{samples.push(serde_json::json!({"variant":variant,"round":round,"ms":elapsed_ms,"executed":r.executed,"affected":r.affected,"stored_rows":count}));parses.push(serde_json::json!({"variant":variant,"round":round,"ms":parse_ms}));}}}
Ok(serde_json::json!({"engine":$engine,"path":"product-scanner-worker-audit","history_registry_shim":true,"transaction":"default autocommit","affected_semantics":"native driver receipts; PostgreSQL SELECT CommandComplete contributes selected rows, MySQL SELECT contributes zero; stored rows independently checked","rows":rows,"bytes":bytes,"rounds":rounds,"warmup_per_variant":1,"samples":samples,"parse_samples":parses}))}
};}
remote_benchmark!(mysql_bench,mysql_connection,mysql,"mysql");remote_benchmark!(pg_bench,pg_connection,pg,"pg");


