#[tokio::main]async fn main()->Result<()>{let args:Vec<_>=std::env::args().collect();let mode=args.get(1).map(String::as_str).unwrap_or("sqlite");if mode=="semantics"{sqlite_semantics().await?;sqlite_cancel().await?;return Ok(())}let rows=args.get(2).and_then(|s|s.parse().ok()).unwrap_or(6000);let rounds=args.get(3).and_then(|s|s.parse().ok()).unwrap_or(5);let payload=args.get(4).and_then(|s|s.parse().ok()).unwrap_or(1024);let r=match mode {"mysql"=>mysql_bench(rows,rounds,payload).await?,"pg"=>pg_bench(rows,rounds,payload).await?,_=>sqlite_bench(rows,rounds,payload).await?};println!("{}",serde_json::to_string(&r)?);Ok(())}
